mapper.select:
SELECT id, sku_id, stock_num, version, update_time
FROM stock_count
WHERE sku_id = #{skuId}

mapper.update:
UPDATE stock_count
SET stock_num = stock_num - #{changeNum},
    version = version + 1
WHERE sku_id = #{skuId}
  AND version = #{version}
  AND stock_num >= #{changeNum}

UPDATE stock_count
SET stock_num = stock_num + #{changeNum},
    version = version + 1
WHERE sku_id = #{skuId}
  AND version = #{version}
